gchar * /* <=== ev_mkdtemp */ 
ev_mkdtemp (const char        *template,
            GError           **error)
{
        const char *tmp;
        char *name;

        if ((tmp = _ev_tmp_dir (error)) == NULL)
              return NULL;

        name = g_build_filename (tmp, template, NULL);
        if (g_mkdtemp (name) == NULL) {
		int errsv = errno;

                g_set_error (error, G_IO_ERROR, g_io_error_from_errno (errsv),
                             _("Failed to create a temporary directory: %s"),
                             g_strerror (errsv));

                g_free (name);
                return NULL;
        }

        return name;
}

static gboolean /* <=== _ev_dir_ensure_exists */ 
_ev_dir_ensure_exists (const gchar *dir,
                       int          mode,
                       GError     **error)
{
        int errsv;
        char *display_name;

        g_return_val_if_fail (dir != NULL, FALSE);

        errno = 0;
	if (g_mkdir_with_parents (dir, mode) == 0)
		return TRUE;

        errsv = errno;
	if (errsv == EEXIST && g_file_test (dir, G_FILE_TEST_IS_DIR))
                return TRUE;

        display_name = g_filename_display_name (dir);
        g_set_error (error, G_IO_ERROR, g_io_error_from_errno (errsv),
                     "Failed to create directory '%s': %s",
                     display_name, g_strerror (errsv));
        g_free (display_name);

	return FALSE;
}

static const char * /* <=== _ev_tmp_dir */ 
_ev_tmp_dir (GError **error)
{

        if (tmp_dir == NULL) {
                const gchar *prgname;
                gchar *dirname;

                prgname = g_get_prgname ();
                dirname = g_strdup_printf ("%s-%u", prgname ? prgname : "unknown", getpid ());
                tmp_dir = g_build_filename (g_get_tmp_dir (), dirname, NULL);
                g_free (dirname);
        }

        if (!_ev_dir_ensure_exists (tmp_dir, 0700, error))
                return NULL;

	return tmp_dir;
}

